/// Render delimiter aliases that are valid after \left and \right.
fn render_delimiter_command_table(output: &mut String) {
    output.push_str("pub(crate) const DELIMITER_COMMAND_CHARS: &[TexCommandChar] = &[\n");
    for &(command, ch) in delimiter_command_aliases() {
        output.push_str(&format!(
            "    TexCommandChar {{ command: \"{command}\", ch: {} }},\n",
            char_literal(ch)
        ));
    }
    output.push_str("];\n\n");
}

/// Render the glyphs appended by MathType's big-operator templates.
fn render_big_operator_table(output: &mut String, rows: &[(Target, CharRecord)]) {
    output.push_str("pub(crate) const BIG_OPERATOR_GLYPHS: &[BigOperatorGlyph] = &[\n");
    for (target, record) in rows
        .iter()
        .filter(|(target, _)| target.category == Category::BigOperator)
    {
        let name = match target.selector {
            Selector::BigOperator { name } | Selector::NamedMtCode { name, .. } => Some(name),
            Selector::LastChar { .. } if target.name.starts_with("bigop_") => {
                target.name.strip_prefix("bigop_")
            }
            _ => None,
        };
        if let Some(name) = name {
            output.push_str(&format!(
                "    BigOperatorGlyph {{ name: \"{name}\", typeface: {}, mtcode: 0x{:04x}, font_pos: 0x{:02x}, explicit_font: {}, font_style_selector: {} }},\n",
                typeface_literal(record.typeface),
                record.mtcode,
                record.font_pos.expect("big operators must have font positions"),
                explicit_font_literal(record.explicit_font),
                option_byte_literal(record.font_style_selector)
            ));
        }
    }
    output.push_str("];\n");
}

/// Extract a bare control word from simple probes such as "$\\alpha$".
pub(super) fn tex_command_from_formula(formula: &str) -> Option<&str> {
    let body = formula.strip_prefix("$\\")?.strip_suffix("$")?;
    body.chars()
        .all(|ch| ch.is_ascii_alphabetic())
        .then_some(body)
}

