/// Return the logical character represented by a CHAR selector.
fn selector_char(selector: Selector) -> Option<char> {
    match selector {
        Selector::FontPos { ch, .. }
        | Selector::PlainChar { ch, .. }
        | Selector::VisibleCharIndex { ch, .. }
        | Selector::RawTextRun { ch, .. }
        | Selector::LastChar { ch } => Some(ch),
        Selector::LastInferredChar
        | Selector::NamedMtCode { .. }
        | Selector::BigOperator { .. } => None,
    }
}

/// Return the parser-facing character key for one generated row.
fn target_logical_char(target: Target, record: CharRecord) -> Option<char> {
    selector_char(target.selector).or_else(|| match target.selector {
        Selector::LastInferredChar => char::from_u32(record.mtcode as u32),
        _ => None,
    })
}
